#define _DARWIN_C_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv)
{
    if (argc != 3) return 2;
    void *library = dlopen("/usr/lib/libz.1.dylib", RTLD_NOW | RTLD_LOCAL);
    if (!library) return 3;
    void *symbol = dlsym(library, argv[1]);
    if (!symbol) {
        printf("SYMBOL_ABSENT %s\n", argv[1]);
        return 0;
    }
    Dl_info info = {0};
    if (!dladdr(symbol, &info) || !info.dli_fname) return 4;
    printf("SYMBOL_PRESENT %s image=%s length=%s\n", argv[1], info.dli_fname, argv[2]);
    fflush(stdout);
    long length = strtol(argv[2], NULL, 10);
    unsigned long result;
    if (strcmp(argv[1], "crc32_combine") == 0 || strcmp(argv[1], "crc32_combine64") == 0) {
        unsigned long (*combine)(unsigned long, unsigned long, long) = symbol;
        result = combine(0, 0, length);
    } else if (strcmp(argv[1], "crc32_combine_gen") == 0 || strcmp(argv[1], "crc32_combine_gen64") == 0) {
        unsigned long (*generate)(long) = symbol;
        result = generate(length);
    } else return 5;
    printf("RETURNED %lu\n", result);
    dlclose(library);
    return 0;
}

import hashlib
import json
import platform
import subprocess
from pathlib import Path

root = Path('/private/tmp/bpr-rfc0038-official-qt-20261016')
results = []
for architecture in ('arm64', 'x86_64'):
    executable = root / ('apple-crc-' + architecture)
    compile_command = ['/usr/bin/clang', '-O1', '-arch', architecture, str(root / 'apple_crc_probe.c'), '-o', str(executable)]
    build = subprocess.run(compile_command, capture_output=True, text=True, timeout=60)
    assert build.returncode == 0, build.stderr
    for symbol in ('crc32_combine', 'crc32_combine64', 'crc32_combine_gen', 'crc32_combine_gen64'):
        for length in ('-1', '0', '1'):
            command = [str(executable), symbol, length]
            try:
                result = subprocess.run(command, capture_output=True, text=True, timeout=2)
                row = {'architecture': architecture, 'symbol': symbol, 'length': int(length), 'exitCode': result.returncode, 'output': result.stdout.strip(), 'error': result.stderr.strip()}
            except subprocess.TimeoutExpired as error:
                row = {'architecture': architecture, 'symbol': symbol, 'length': int(length), 'exitCode': None, 'outcome': 'timeout; owned subprocess killed and reaped by subprocess.run', 'output': (error.stdout or b'').decode().strip()}
            results.append(row)
record = {'host': platform.mac_ver(), 'sourceSHA256': hashlib.sha256((root/'apple_crc_probe.c').read_bytes()).hexdigest(), 'results': results, 'scope': 'Standalone calls to the current Apple system library. x86_64 is Rosetta, not native Intel qualification; no app execution or OS-wide patch claim.'}
(root/'apple-crc-results.json').write_text(json.dumps(record, indent=2)+'\n')
print(json.dumps(record, indent=2))

#define _DARWIN_C_SOURCE
#include <dlfcn.h>
#include <mach-o/dyld.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

static unsigned external_dbus_loads;
static unsigned qt_dbus_loads;

static void image_added(const struct mach_header *header, intptr_t slide)
{
    (void)slide;
    for (uint32_t index = 0; index < _dyld_image_count(); ++index) {
        if (_dyld_get_image_header(index) != header) continue;
        const char *path = _dyld_get_image_name(index);
        const char *name = strrchr(path, '/');
        name = name ? name + 1 : path;
        if (strstr(path, "/QtDBus.framework/")) ++qt_dbus_loads;
        if (strncmp(name, "libdbus-1", 9) == 0) ++external_dbus_loads;
    }
}

int main(int argc, char **argv)
{
    if (argc != 7) return 2;
    _dyld_register_func_for_add_image(image_added);
    for (int index = 1; index < 6; ++index) {
        void *loaded = dlopen(argv[index], RTLD_NOW | RTLD_LOCAL);
        if (!loaded) {
            fprintf(stderr, "LOAD_FAILED %s: %s\n", argv[index], dlerror());
            return 3;
        }
    }
    printf("PACKAGE_IMAGES qt_dbus_loads=%u external_dbus_loads=%u\n", qt_dbus_loads, external_dbus_loads);
    if (qt_dbus_loads != 1 || external_dbus_loads != 0) return 4;
    if (!dlopen(argv[6], RTLD_NOW | RTLD_LOCAL)) return 5;
    printf("NEGATIVE_CONTROL external_dbus_loads=%u\n", external_dbus_loads);
    return external_dbus_loads == 1 ? 0 : 6;
}
